WebLink.url:
{!REQUIRESCRIPT("/soap/ajax/30.0/connection.js")} 
{!REQUIRESCRIPT("/soap/ajax/30.0/apex.js")}

var query = "select Id, ExemptBlocking__c from Inventory__c where Id = '{!Inventory__c.Id}' limit 1"; 

var result = sforce.connection.query(query); 
var records = result.getArray("records"); 

var myObj = records[0];

myObj.ExemptBlocking__c  = true;

var results = sforce.connection.update([myObj]);

var isSuccess = results[0].getBoolean("success");

if (isSuccess){
alert('Inventory is exempted from blocking.');
} else {
alert(results[0].get("errors").get("message"));
}
